import './style.css';
import {feeLabels,statusColors,roles,dateToday} from '../shared/schema.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const S={user:null,meta:null,cache:{},page:location.hash.slice(1)||'dashboard',period:dateToday().slice(0,7),entity:'',building:'',search:'',pageNum:1,items:[],total:0,report:null,busy:false};
const money=n=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(Number(n)||0)+' ₫';
const compact=n=>Math.abs(n)>=1e9?(n/1e9).toFixed(2)+' tỷ':Math.abs(n)>=1e6?(n/1e6).toFixed(1)+' tr':money(n);
const num=n=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:1}).format(Number(n)||0);
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?String(value).slice(0,10).split('-').reverse().join('/'):'—';
const paths={dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',building:'M4 21V4h12v17M16 9h4v12M8 8h4M8 12h4M8 16h4M2 21h20',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6',receipt:'M4 3l2 2 2-2 2 2 2-2 2 2 2-2 2 2 2-2v18l-2-2-2 2-2-2-2 2-2-2-2 2-2-2-2 2zM8 9h8M8 13h8M8 17h4',credit:'M3 5h18v14H3zM3 10h18M7 15h4',wallet:'M3 6h16v15H3zM3 6V3h15M15 10h6v6h-6zM17 13h1',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',tool:'M14 6a5 5 0 0 0-7 6L3 16a3 3 0 0 0 4 4l5-5a5 5 0 0 0 6-7l-4 3-3-3z',life:'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18M6 6l4 4M14 14l4 4M18 6l-4 4M10 14l-4 4M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8',check:'M9 11l3 3L22 4M21 12v8H3V4h13',target:'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18M12 7a5 5 0 1 1 0 10 5 5 0 0 1 0-10M12 11v2',chart:'M3 3v18h18M7 16l4-5 4 2 6-8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',briefcase:'M3 7h18v14H3zM8 7V3h8v4M3 12h18M10 12v3h4v-3',tag:'M20 13l-7 7L3 10V3h7zM7 7h.01',repeat:'M3 8h15l-4-4M21 16H6l4 4',percent:'M4 20L20 4M8 6a2 2 0 1 1-4 0 2 2 0 0 1 4 0M20 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',gauge:'M4 19a10 10 0 1 1 16 0M12 13l5-5M12 13v1',calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h3M14 14h2',list:'M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1',search:'M10 3a7 7 0 1 1 0 14 7 7 0 0 1 0-14M15 15l6 6',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',logout:'M9 5H3v14h6M9 12h12M17 8l4 4-4 4',menu:'M3 6h18M3 12h18M3 18h18',shield:'M12 3l9 4v6c0 5-9 9-9 9S3 18 3 13V7zM8 12l3 3 5-6',clock:'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18M12 7v5l3 2',gem:'M12 2l9 5v10l-9 5-9-5V7zM3 7l9 5 9-5M12 12v10',close:'M5 5l14 14M19 5L5 19',edit:'M4 20l4-1L20 7l-3-3L5 16zM14 7l3 3'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const badge=(text,color=statusColors[text]||'gray')=>`<span class="badge ${color}"><i></i>${e(text)}</span>`;
function toast(text,error=false){const el=document.querySelector('#toast');el.textContent=text;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
async function api(path,data,method){const response=await fetch('/api'+path,{method:method||(data?'POST':'GET'),headers:{'Content-Type':'application/json','X-ERP-Request':'1'},...(data?{body:JSON.stringify(data)}:{})});let result;try{result=await response.json();}catch{throw new Error('Không thể đọc phản hồi máy chủ.');}if(!response.ok){if(response.status===401&&S.user){S.user=null;await init();}throw new Error(result.error||'Yêu cầu thất bại.');}return result;}
function lookup(collection,id){return S.cache[collection]?.find(row=>row.id===id);}
function label(collection,id){const row=lookup(collection,id);if(!row)return id?'Bản ghi liên kết':'—';return row.name||row.code;}
function value(row,key,collection){const field=S.meta.schemas[collection]?.fields.find(f=>f.key===key);const raw=row[key];if(field?.type==='image')return raw?badge('Có ảnh','green'):'—';if(field?.ref)return e(label(field.ref,raw));if(key==='tenantId')return e(label('tenants',raw));if(key==='unitId')return e(label('units',raw));if(key==='invoiceId')return e(label('invoices',raw));if(key==='legalEntityId')return e(label('legalEntities',raw));if(key==='status')return badge(raw);if(key==='fee')return e(feeLabels[raw]||raw);if(key==='source')return e({approvedTasks:'Công việc đã duyệt',resolvedTickets:'Sự cố nghiệm thu',qualityScore:'Điểm chất lượng dịch vụ',manual:'Nhập có nguồn'}[raw]||raw);if(key==='basis')return e({area:'Theo m²',flat:'Khoán',usage:'Công tơ'}[raw]);if(field?.type==='date'||key.endsWith('Date')||key==='date')return date(raw);if(['amount','total','paid','unitPrice','baseSalary','bonusCap','cost','rentPerM2','totalDebit','totalCredit'].includes(key))return `<span class="amount">${raw===undefined?'—':row.currency==='USD'&&key==='unitPrice'?num(raw)+' USD':money(raw)}</span>`;if(field?.type==='number')return num(raw);return e(raw??'—');}
const extraLabels={code:'Mã',tenantId:'Khách thuê',unitId:'Mặt bằng',period:'Kỳ thu',total:'Tổng hóa đơn',paid:'Đã thu',status:'Trạng thái'};
const pageLabels={ledger:'Sổ cái & cân đối',dashboard:'Tổng quan điều hành',cashflow:'Dòng tiền & hiệu quả',payroll:'Lương thưởng chạy thử',modules:'Bản đồ 38 module',audit:'Nhật ký thay đổi',users:'Tài khoản & phân quyền',periods:'Chốt kỳ dữ liệu',portal:'Cổng khách thuê'};
const title=()=>S.meta?.schemas[S.page]?.label||pageLabels[S.page]||'Tổng quan điều hành';
const userCanWrite=collection=>S.meta.schemas[collection]?.writers.includes(S.user.role);
function navItem(key,text,ico){return `<button class="nav-item ${S.page===key?'active':''}" data-page="${key}">${icon(ico)}<span>${e(text)}</span>${S.page===key?'<span class="nav-dot"></span>':''}</button>`;}
function shell(content){
 const groups={};for(const [key,schema] of Object.entries(S.meta.schemas)){(groups[schema.group]??=[]).push([key,schema]);}
 const nav=Object.entries(groups).map(([group,items])=>`<details class="nav-group" ${items.some(([k])=>k===S.page)||['TÀI SẢN & KHÁCH THUÊ','TÀI CHÍNH'].includes(group)?'open':''}><summary>${e(group)}<span>⌄</span></summary>${items.map(([key,s])=>navItem(key,s.label,s.icon)).join('')}</details>`).join('');
 app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-icon">${icon('gem',25)}</span><span>GEMS OFFICE<small>BUILDING ERP</small></span></a><div class="workspace-chip"><span class="workspace-icon">G</span><div>Gems Workspace<small>${S.meta.demo?'Không gian dữ liệu mẫu':'Không gian doanh nghiệp'}</small></div></div><nav aria-label="Phân hệ ERP">${navItem(S.user.role==='tenant'?'portal':'dashboard',S.user.role==='tenant'?'Cổng khách thuê':'Tổng quan điều hành','dashboard')}${S.user.role!=='tenant'?navItem('cashflow','Dòng tiền & hiệu quả','chart'):''}${nav}${['admin','manager','accountant'].includes(S.user.role)?navItem('ledger','Sổ cái & cân đối','receipt'):''}${['admin','manager','accountant'].includes(S.user.role)?navItem('payroll','Lương thưởng chạy thử','wallet'):''}${navItem('modules','Bản đồ nghiệp vụ Excel','list')}${S.user.role==='admin'?navItem('users','Tài khoản & phân quyền','shield')+navItem('periods','Chốt kỳ dữ liệu','calendar')+navItem('audit','Nhật ký thay đổi','clock'):''}</nav><div class="sidebar-bottom"><span class="avatar">${e(S.user.name.slice(0,1))}</span><div><strong>${e(S.user.name)}</strong><small>${e(roles[S.user.role])}</small></div><button id="logout" aria-label="Đăng xuất">${icon('logout')}</button></div></aside><button class="mobile-backdrop" id="mobile-backdrop" aria-label="Đóng menu" hidden></button><div class="main-area"><header class="topbar"><button class="mobile-menu" id="mobile-menu" aria-label="Mở menu">${icon('menu')}</button><span class="breadcrumb">Không gian làm việc <span>/</span> <strong>${e(title())}</strong></span><div class="topbar-right"><span class="live-dot"></span><span>Dữ liệu trực tiếp</span><span class="topbar-divider"></span><button class="icon-button" data-page="tickets" aria-label="Xem yêu cầu dịch vụ">${icon('bell',19)}</button><span class="avatar small">${e(S.user.name.slice(0,1))}</span></div></header><main class="content">${S.meta.demo?`<div class="demo-strip">${icon('shield',15)} Dữ liệu minh họa · File Excel cung cấp yêu cầu nghiệp vụ, không chứa giao dịch thực tế.</div>`:''}<section class="page-heading"><div><p class="eyebrow">GEMS OFFICE / ${S.user.role==='tenant'?'TENANT PORTAL':'ERP WORKSPACE'}</p><h1>${e(title())}</h1><p class="page-subtitle">${subtitle()}</p></div><div class="heading-actions">${S.user.role==='admin'?'<button class="button secondary" id="export-all">'+icon('download',16)+' Xuất dữ liệu</button>':''}<div class="date-chip">${icon('calendar',16)} ${date(dateToday())}</div></div></section>${filters()}${content}<footer class="page-footer"><span>Gems Office ERP <span class="footer-dot">·</span> Dữ liệu tập trung, hai luồng liên thông</span><span>38 module trong bản yêu cầu</span></footer></main></div></div>`;
 document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>go(button.dataset.page));
 document.querySelector('#logout').onclick=async()=>{try{await api('/auth/logout',{});S.user=null;await init();}catch(error){toast(error.message,true);}};
 document.querySelector('#mobile-menu').onclick=()=>{const open=document.querySelector('.sidebar').classList.toggle('mobile-open');document.querySelector('#mobile-backdrop').hidden=!open;};
 document.querySelector('#mobile-backdrop').onclick=()=>{document.querySelector('.sidebar').classList.remove('mobile-open');document.querySelector('#mobile-backdrop').hidden=true;};
 document.querySelector('#export-all')?.addEventListener('click',()=>downloadJSON());
 document.querySelector('#filter-period').onchange=event=>{S.period=event.target.value||dateToday().slice(0,7);refresh().catch(err=>toast(err.message,true));};
 document.querySelector('#filter-entity')?.addEventListener('change',event=>{S.entity=event.target.value;S.building='';S.pageNum=1;refresh().catch(err=>toast(err.message,true));});
 document.querySelector('#filter-building')?.addEventListener('change',event=>{S.building=event.target.value;S.pageNum=1;refresh().catch(err=>toast(err.message,true));});
}
function subtitle(){return {ledger:'Hạch toán kép từ hóa đơn, thu tiền, ghi nhận và thanh toán chi phí.',dashboard:'Bức tranh tài chính, vận hành và hiệu suất trong một không gian.',cashflow:'Đối chiếu thu chi thực tế, công nợ và hiệu quả từng dự án.',payroll:'Tính song song theo KPI. Chưa dùng để trả lương chính thức.',modules:'Đối chiếu phạm vi triển khai với 38 module và 41 yêu cầu từ Excel.',audit:'Ai thay đổi dữ liệu, thay đổi gì và vào thời điểm nào.',users:'Quản lý vai trò và phạm vi truy cập ở phía máy chủ.',periods:'Đóng băng số liệu của kỳ đã chốt, giữ lại báo cáo đối soát.',portal:'Hợp đồng, hóa đơn, chỉ số điện nước và yêu cầu của doanh nghiệp bạn.'}[S.page]||'Quản lý dữ liệu, theo dõi lịch sử và kết nối với các phân hệ liên quan.';}
function filters(){return `<div class="scope-bar"><span class="scope-label">${icon('grid',16)} Phạm vi dữ liệu</span><label class="sr-only" for="filter-entity">Lọc pháp nhân</label><select id="filter-entity"><option value="">Tất cả pháp nhân</option>${(S.cache.legalEntities||[]).map(row=>`<option value="${e(row.id)}" ${S.entity===row.id?'selected':''}>${e(row.name)}</option>`).join('')}</select><label class="sr-only" for="filter-building">Lọc tòa nhà</label><select id="filter-building"><option value="">Tất cả tòa nhà</option>${(S.cache.buildings||[]).filter(row=>!S.entity||row.legalEntityId===S.entity).map(row=>`<option value="${e(row.id)}" ${S.building===row.id?'selected':''}>${e(row.name)}</option>`).join('')}</select><span class="scope-spacer"></span><label for="filter-period">Kỳ báo cáo</label><input type="month" id="filter-period" value="${e(S.period)}"></div>`;}
function chart(months){const max=Math.max(1,...months.flatMap(m=>[m.incoming,m.outgoing]));return `<div class="cash-chart" role="img" aria-label="Biểu đồ dòng tiền theo tháng">${months.map(m=>`<div class="chart-group ${m.forecast?'forecast':''}"><div class="bar-pair"><div class="bar incoming" style="height:${Math.max(2,m.incoming/max*100)}%" title="Thu: ${money(m.incoming)}"></div><div class="bar outgoing" style="height:${Math.max(2,m.outgoing/max*100)}%" title="Chi: ${money(m.outgoing)}"></div></div><span>${m.period.slice(5)}/${m.period.slice(2,4)}</span>${m.forecast?'<small>Dự báo</small>':''}</div>`).join('')}</div>`;}
function stat(iconName,labelText,valueText,note,color='teal'){return `<article class="stat-card"><div class="stat-top"><span>${e(labelText)}</span><span class="stat-icon ${color}">${icon(iconName,19)}</span></div><strong>${e(valueText)}</strong><div class="stat-note">${e(note)}</div></article>`;}
function dashboard(){const r=S.report;const alerts=r.expiring.length+r.maintenance.length+r.tickets.length;const pending=r.approvals.length;
 const projectRows=r.project.map(p=>`<tr><td><div class="project-cell"><span class="building-tile">${icon('building',17)}</span><div><strong>${e(p.name)}</strong><small>${e(p.model)}</small></div></div></td><td><div class="occupancy-cell"><span>${num(p.occupancy)}%</span><div class="progress-track"><i style="width:${Math.min(100,p.occupancy)}%"></i></div></div></td><td class="amount">${compact(p.revenue)}</td><td class="amount ${p.profit<0?'text-red':'text-teal'}">${compact(p.profit)}</td><td>${badge(p.occupancy>=70?'Ổn định':'Cần khai thác',p.occupancy>=70?'green':'amber')}</td></tr>`).join('');
 const alertItems=[...r.maintenance.map(a=>({name:'Đến hạn bảo trì: '+a.name,sub:label('buildings',a.buildingId),icon:'tool',page:'assets',color:'amber'})),...r.expiring.map(c=>({name:'Hợp đồng sắp hết hạn',sub:label('tenants',c.tenantId)+' · '+date(c.endDate),icon:'file',page:'contracts',color:'blue'})),...r.tickets.map(t=>({name:t.name,sub:label('buildings',t.buildingId)+' · '+t.priority,icon:'life',page:'tickets',color:t.priority==='Khẩn cấp'?'red':'blue'}))].slice(0,5);
 const departmentRows=r.departments.map(d=>`<div class="department-row"><span class="dept-icon">${e(d.name.slice(0,2))}</span><div class="dept-name"><strong>${e({TCKT:'Tài chính kế toán',PKD:'Kinh doanh',BQL:'Ban quản lý',MKT:'Marketing',HCNS:'Hành chính nhân sự'}[d.name])}</strong><small>${d.approved}/${d.total} công việc được duyệt</small></div><div class="department-progress"><div class="progress-track"><i style="width:${d.total?d.approved/d.total*100:0}%"></i></div><span>${d.total?Math.round(d.approved/d.total*100):0}%</span></div></div>`).join('');
 shell(`<div class="stat-grid">${stat('receipt','Doanh thu trước thuế',compact(r.revenue),`Từ hóa đơn kỳ ${S.period}`)}${stat('building','Tỷ lệ lấp đầy',num(r.occupancy)+'%',`${num(r.vacantArea)} m² đang trống`,'blue')}${stat('wallet','Công nợ phải thu',compact(r.debt),'Tất cả kỳ · đã trừ khoản thu','amber')}${stat('chart','Dòng tiền thuần',compact(r.cashIn-r.cashOut),'Thu thực tế trừ chi thực tế','purple')}</div><div class="dashboard-grid"><section class="card cashflow-card"><div class="card-heading"><div><h2>Dòng tiền & dự báo</h2><p>Thực tế 6 kỳ · dự báo 3 kỳ từ hợp đồng</p></div><button class="text-button" data-page="cashflow">Xem chi tiết ${icon('arrow',14)}</button></div><div class="chart-summary"><strong>${compact(r.cashIn)}</strong><span>Tiền thực thu trong kỳ</span><div class="chart-legend"><span><i class="legend-in"></i> Thu</span><span><i class="legend-out"></i> Chi</span></div></div>${chart(r.months)}<p class="chart-note">${icon('clock',13)} ${e(r.forecastNote)}</p></section><section class="card portfolio-card"><div class="card-heading"><h2>Danh mục vận hành</h2><span class="tag">${r.buildings} tòa nhà</span></div><div class="occupancy-ring" style="--occupancy:${Math.max(0,Math.min(100,r.occupancy))}%"><div><strong>${num(r.occupancy)}<small>%</small></strong><span>diện tích lấp đầy</span></div></div><div class="portfolio-stats"><div><strong>${r.contracts}</strong><span>Hợp đồng hiệu lực</span></div><div><strong>${r.tenants}</strong><span>Khách thuê</span></div><div><strong>${r.units}</strong><span>Mặt bằng</span></div></div><button class="portfolio-link" data-page="units">Khám phá danh mục ${icon('arrow',15)}</button></section><section class="card projects-card"><div class="card-heading"><div><h2>Hiệu quả từng tòa nhà</h2><p>Doanh thu và chi phí theo kỳ đang chọn</p></div><button class="text-button" data-page="buildings">Tất cả tòa nhà ${icon('arrow',14)}</button></div><div class="table-scroll"><table><thead><tr><th>TÒA NHÀ</th><th>LẤP ĐẦY</th><th>DOANH THU</th><th>LÃI / LỖ</th><th>ĐÁNH GIÁ</th></tr></thead><tbody>${projectRows||'<tr><td colspan="5" class="empty-cell">Chưa có tòa nhà. Thêm danh mục để bắt đầu.</td></tr>'}</tbody></table></div></section><section class="card alerts-card"><div class="card-heading"><h2>Cần chú ý</h2><span class="count-badge amber">${alerts}</span></div><div class="alert-list">${alertItems.map(a=>`<button class="alert-item" data-page="${a.page}"><span class="alert-icon ${a.color}">${icon(a.icon,16)}</span><span><strong>${e(a.name)}</strong><small>${e(a.sub)}</small></span>${icon('arrow',13)}</button>`).join('')||'<div class="empty-small">Không có cảnh báo trong phạm vi này.</div>'}</div></section><section class="card departments-card"><div class="card-heading"><div><h2>Hiệu suất phòng ban</h2><p>Chỉ tính công việc có hạn hoàn thành trong kỳ</p></div><button class="text-button" data-page="tasks">Xem công việc ${icon('arrow',14)}</button></div>${departmentRows}</section><section class="card approval-card"><span class="approval-icon">${icon('check',26)}</span><h2>Hàng đợi phê duyệt</h2><strong>${pending}</strong><p>Công việc đang chờ trưởng phòng xác nhận. Quyết định ghi ngược vào bản ghi nhân viên.</p><button class="button primary" data-page="tasks">Mở hàng đợi ${icon('arrow',15)}</button></section><section class="card"><div class="card-heading"><h2>Tiến độ vòng đời dự án</h2><button class="text-button" data-page="projectFlows">Xem quy trình ${icon('arrow',14)}</button></div><div class="alert-list">${r.flows.map(f=>`<button class="alert-item" data-page="projectFlows"><span class="alert-icon teal">${icon('list',16)}</span><span><strong>${e(f.name)}</strong><small>${e(f.currentStepName)} · ${Math.round((f.currentStep+(f.status==='Đã hoàn thành'?1:0))/f.steps.length*100)}%</small></span></button>`).join('')||'<p class="empty-small">Chưa có quy trình dự án trong phạm vi này.</p>'}</div></section><section class="card"><div class="card-heading"><h2>Chất lượng dịch vụ</h2><button class="text-button" data-page="qualityChecks">Phiếu đánh giá ${icon('arrow',14)}</button></div><div class="alert-list">${r.quality.slice(0,5).map(q=>`<button class="alert-item" data-page="qualityChecks"><span class="alert-icon teal">${icon('check',16)}</span><span><strong>${e(label('employees',q.employeeId))}</strong><small>${e(q.serviceRole)} · ${num(q.score)}/100 · ${e(label('buildings',q.buildingId))}</small></span></button>`).join('')||'<p class="empty-small">Chưa có phiếu chất lượng trong kỳ.</p>'}</div></section></div>`);
 bindNav();}
function bindNav(){document.querySelectorAll('main [data-page]').forEach(button=>button.onclick=()=>go(button.dataset.page));}
function recordActions(collection,row){const role=S.user.role;let actions=`<button class="row-button" data-detail="${e(row.id)}" aria-label="Xem ${e(row.name||row.code)}">Xem</button>`;
 if(userCanWrite(collection)&&!['prices','exchangeRates','feeTypes','payments'].includes(collection))actions+=`<button class="row-button" data-edit="${row.id}" aria-label="Sửa ${e(row.name||row.code)}">${icon('edit',14)}</button>`;
 const act=(action,text)=>`<button class="row-button teal" data-action="${action}" data-id="${row.id}">${e(text)}</button>`;
 if(collection==='invoices'){if(['admin','accountant'].includes(role)&&row.paid<row.total&&row.status!=='Đã hủy')actions+=act('pay','Thu tiền');actions+=`<button class="row-button" data-print="${row.id}">PDF</button>`;}
 if(collection==='contracts'&&row.status==='Hiệu lực'&&['admin','accountant'].includes(role)&&Number(row.depositReceived||0)<Number(row.deposit||0))actions+=act('receiveDeposit','Nhận cọc');
 if(collection==='contracts'&&['admin','manager','accountant'].includes(role)){if(row.status==='Hiệu lực')actions+=act('close','Thanh lý');else if(row.depositBalance>0)actions+=act('refundDeposit','Hoàn cọc');}
 if(collection==='tasks'){if(['Chưa hoàn thành','Bị trả lại'].includes(row.status)&&(['admin','manager'].includes(role)||row.employeeId===S.user.scope.employeeId))actions+=act('submit','Gửi duyệt');if(row.status==='Chờ duyệt'&&['admin','manager'].includes(role))actions+=act('approve','Duyệt')+act('reject','Trả lại');}
 if(collection==='expenses'){if(row.status==='Chờ duyệt'&&['admin','manager'].includes(role))actions+=act('approve','Duyệt');if(row.status==='Đã duyệt'&&['admin','accountant'].includes(role))actions+=act('pay','Thanh toán');}
 if(collection==='tickets'){if(row.status==='Mới'&&['admin','manager','technician'].includes(role))actions+=act('assign','Phân công');if(row.status==='Đang xử lý'&&['admin','manager','technician'].includes(role))actions+=act('resolve','Đã xử lý');if(row.status==='Chờ nghiệm thu'&&['admin','manager','tenant'].includes(role))actions+=act('accept','Nghiệm thu');}
 if(collection==='journalEntries'&&['admin','accountant'].includes(role)&&!row.reversalOf)actions+=act('reverse','Đảo bút toán');
 if(collection==='inventoryItems'&&['admin','manager','technician'].includes(role))actions+=act('receive','Nhập kho')+act('issue','Xuất kho');
 if(collection==='purchaseOrders'&&['admin','manager'].includes(role)){if(row.status==='Chờ duyệt')actions+=act('approve','Duyệt');if(row.status==='Đã duyệt')actions+=act('receive','Nhận hàng');}
 if(collection==='projectFlows'&&row.status==='Đang thực hiện'&&['admin','manager'].includes(role))actions+=act('advance','Chuyển bước');
 if(collection==='appraisals')actions+=`<button class="row-button teal" data-model="${row.id}">3 kịch bản</button>`;
 return actions;
}
function records(){const schema=S.meta.schemas[S.page];const columns=schema.columns;
 const rows=S.items.map(row=>`<tr><td class="code-cell">${e(row.code)}</td>${columns.filter(k=>k!=='code').map(key=>`<td>${value(row,key,S.page)}</td>`).join('')}<td><div class="row-actions">${recordActions(S.page,row)}</div></td></tr>`).join('');
 const notices={prices:'Đơn giá thuộc từng hợp đồng + loại phí + ngày hiệu lực. Bổ sung mốc mới, không ghi đè lịch sử.',exchangeRates:'Một mốc tỷ giá duy nhất mỗi hợp đồng/ngày. Chỉ áp dụng cho giá USD của đúng hợp đồng.',feeTypes:'Thuế suất theo loại phí có hiệu lực theo ngày; số thuế trên hóa đơn đã phát hành không bị tính lại.',invoices:'Hóa đơn nội bộ theo từng pháp nhân, chụp lại giá/thuế lúc lập. Chưa tích hợp phát hành hóa đơn điện tử.',tasks:'Bốn trạng thái: chưa hoàn thành → chờ duyệt → đã duyệt hoặc bị trả lại → làm lại và gửi duyệt.',payments:'Khoản thu được ghi từ màn hình hóa đơn; cho phép thu nhiều lần và cấn trừ cọc ở kỳ cuối.',kpis:'KPI thuộc chức danh. Tổng trọng số mỗi chức danh/kỳ phải bằng 100% để chạy thử thưởng.',appraisals:'Mô hình 120 tháng với Master Lease, 60 tháng với Managed Office/Setup; có NPV và IRR.',tickets:'Yêu cầu phát sinh phí được chuyển sang hóa đơn sau nghiệm thu, không thu trực tiếp tại đây.'};
 shell(`${notices[S.page]?'<div class="info-banner">'+icon('shield',16)+'<span>'+e(notices[S.page])+'</span></div>':''}<section class="card records-card"><div class="record-toolbar"><div class="record-title"><h2>${e(schema.label)}</h2><span class="tag">${S.total} bản ghi</span></div><div class="toolbar-actions"><div class="search-box">${icon('search',16)}<label for="record-search" class="sr-only">Tìm kiếm bản ghi</label><input id="record-search" placeholder="Tìm tên, mã, nội dung…" value="${e(S.search)}"></div><button class="button secondary small-button" id="export-csv" title="Xuất dữ liệu hiển thị">${icon('download',16)} CSV</button>${S.user.role==='admin'&&userCanWrite(S.page)&&!['payments'].includes(S.page)?'<button class="button secondary small-button" id="import-records">Nhập JSON</button>':''}${S.page==='invoices'&&['admin','accountant'].includes(S.user.role)?'<button class="button primary small-button" id="generate-invoice">'+icon('plus',16)+' Lập hóa đơn</button>':userCanWrite(S.page)&&S.page!=='payments'?'<button class="button primary small-button" id="add-record">'+icon('plus',16)+' Thêm mới</button>':''}</div></div><div class="table-scroll"><table><thead><tr><th>MÃ</th>${columns.filter(k=>k!=='code').map(key=>'<th>'+e(schema.fields.find(f=>f.key===key)?.label||extraLabels[key]||key)+'</th>').join('')}<th>THAO TÁC</th></tr></thead><tbody>${rows||'<tr><td colspan="'+(columns.length+2)+'" class="empty-cell">'+icon(schema.icon,30)+'<strong>Chưa có dữ liệu phù hợp</strong><p>Thêm bản ghi mới hoặc thay đổi bộ lọc.</p></td></tr>'}</tbody></table></div><div class="table-footer"><span>Trang ${S.pageNum} · ${S.items.length} / ${S.total} bản ghi</span><div><button class="row-button" id="prev-page" ${S.pageNum===1?'disabled':''}>← Trước</button><button class="row-button" id="next-page" ${S.pageNum*25>=S.total?'disabled':''}>Sau →</button></div></div></section>`);
 document.querySelector('#add-record')?.addEventListener('click',()=>editRecord());
 document.querySelector('#generate-invoice')?.addEventListener('click',generateInvoice);
 document.querySelectorAll('[data-edit]').forEach(button=>button.onclick=()=>editRecord(S.items.find(r=>r.id===button.dataset.edit)));
 document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>detail(S.items.find(r=>r.id===button.dataset.detail)));
 document.querySelectorAll('[data-action]').forEach(button=>button.onclick=()=>workflow(button.dataset.id,button.dataset.action));
 document.querySelectorAll('[data-print]').forEach(button=>button.onclick=()=>printInvoice(S.items.find(r=>r.id===button.dataset.print)));
 document.querySelectorAll('[data-model]').forEach(button=>button.onclick=()=>showModel(button.dataset.model));
 document.querySelector('#export-csv').onclick=exportCSV;
 document.querySelector('#import-records')?.addEventListener('click',importRecords);
 document.querySelector('#prev-page').onclick=()=>{S.pageNum--;refresh().catch(err=>toast(err.message,true));};document.querySelector('#next-page').onclick=()=>{S.pageNum++;refresh().catch(err=>toast(err.message,true));};
 let timer;document.querySelector('#record-search').oninput=event=>{S.search=event.target.value;clearTimeout(timer);timer=setTimeout(async()=>{S.pageNum=1;try{await refresh();const input=document.querySelector('#record-search');input?.focus();input?.setSelectionRange(S.search.length,S.search.length);}catch(err){toast(err.message,true);}},300);};
}
function openModal(heading,body,submitLabel,onSubmit){modal.innerHTML=`<div class="modal-heading"><div><p class="eyebrow">GEMS OFFICE ERP</p><h2>${e(heading)}</h2></div><button type="button" class="icon-button" id="close-modal" aria-label="Đóng">${icon('close',20)}</button></div>${submitLabel?'<form id="modal-form">':''}<div class="modal-body">${body}</div><div class="modal-footer"><p class="form-error" id="form-error" role="alert"></p><button type="button" class="button secondary" id="cancel-modal">Đóng</button>${submitLabel?`<button type="submit" class="button primary">${e(submitLabel)}</button>`:''}</div>${submitLabel?'</form>':''}`;modal.showModal();modal.querySelector('#close-modal').onclick=()=>modal.close();modal.querySelector('#cancel-modal').onclick=()=>modal.close();if(submitLabel)modal.querySelector('#modal-form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;try{await onSubmit(new FormData(event.target));modal.close();await loadCache();await refresh();}catch(err){modal.querySelector('#form-error').textContent=err.message;}finally{button.disabled=false;}};}
function fieldHTML(field,record={}){let val=record[field.key]??'';if(field.type==='date'&&!val&&['date','startDate','effectiveDate','publishDate','dueDate'].includes(field.key))val=dateToday();if(field.type==='month'&&!val)val=S.period;
 if(field.key==='renewal'&&!val)val=1;const attrs=`id="field-${field.key}" name="${field.key}" ${field.required?'required':''}`;
 let input;if(field.type==='select'){const choices=field.ref?(S.cache[field.ref]||[]).map(r=>[r.id,(r.name||r.code)+(field.ref==='employees'?' · '+r.department:'')]):field.options.map(o=>[o,feeLabels[o]||roles[o]||{area:'Theo m²',flat:'Khoán cố định',usage:'Theo công tơ',approvedTasks:'Số công việc được duyệt',resolvedTickets:'Sự cố đã nghiệm thu',qualityScore:'Điểm chất lượng dịch vụ',manual:'Nhập thủ công có nguồn'}[o]||o]);input=`<select ${attrs}><option value="">Chọn ${e(field.label.toLowerCase())}</option>${choices.map(([key,text])=>`<option value="${e(key)}" ${String(val)===String(key)?'selected':''}>${e(text)}</option>`).join('')}</select>`;}
 else if(field.type==='image')input=`<input ${attrs} type="file" accept="image/png,image/jpeg,image/webp" capture="environment">${val?'<small>Đã có ảnh; chọn ảnh mới để thay.</small>':''}`;
 else if(field.type==='textarea')input=`<textarea ${attrs} rows="3">${e(val)}</textarea>`;
 else input=`<input ${attrs} type="${field.type}" value="${e(val)}" ${field.type==='number'?`step="any" min="${field.min??0}" max="${field.max??1e15}"`:field.type==='text'?'maxlength="200"':''}>`;
 return `<label class="form-field ${field.type==='textarea'?'full-width':''}" for="field-${field.key}"><span>${e(field.label)}${field.required?' <em>*</em>':''}</span>${input}</label>`;}
function editRecord(record){const schema=S.meta.schemas[S.page];openModal((record?'Cập nhật ':'Thêm ')+schema.singular,`<div class="form-grid">${schema.fields.map(f=>fieldHTML(f,record||{})).join('')}</div>`,'Lưu dữ liệu',async form=>{const payload=Object.fromEntries(form);for(const f of schema.fields.filter(f=>f.type==='image')){const file=payload[f.key];if(file?.size){if(file.size>10000000)throw new Error('Ảnh đầu vào tối đa 10 MB.');if(file.size>300000){const bitmap=await createImageBitmap(file);const scale=Math.min(1,1000/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);payload[f.key]=canvas.toDataURL('image/jpeg',.65);bitmap.close();if(payload[f.key].length>420000)throw new Error('Ảnh sau nén còn quá lớn, vui lòng chọn ảnh nhỏ hơn.');}else payload[f.key]=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}else payload[f.key]=record?.[f.key]||'';}if(record)payload.updatedAt=record.updatedAt;for(const f of schema.fields)if(f.type==='number'&&payload[f.key]!=='')payload[f.key]=Number(payload[f.key]);await api('/records/'+S.page+(record?'/'+record.id:''),payload,record?'PUT':'POST');toast(record?'Đã cập nhật bản ghi.':'Đã thêm bản ghi.');});}
function detail(row){const schema=S.meta.schemas[S.page];const fields=[...schema.fields.map(f=>f.key),...['status','depositBalance','compensation','reviewNote','sourceSystem','updatedBy','createdAt','updatedAt'].filter(k=>row[k]!==undefined)];let content=`<div class="detail-code">${e(row.code)}</div><dl class="detail-grid">${fields.map(key=>`<div><dt>${e(schema.fields.find(f=>f.key===key)?.label||({status:'Trạng thái',depositBalance:'Cọc đang giữ',compensation:'Bồi thường dự kiến',reviewNote:'Ghi chú duyệt',sourceSystem:'Nguồn hệ thống',updatedBy:'Người cập nhật',createdAt:'Tạo lúc',updatedAt:'Cập nhật lúc'}[key]||key))}</dt><dd>${value(row,key,S.page)}</dd></div>`).join('')}</dl>`;
 if(row.lines&&S.page==='invoices')content+=`<h3>Chi tiết hóa đơn · số liệu đã chụp</h3><div class="table-scroll"><table><thead><tr><th>Khoản phí</th><th>Trước thuế</th><th>Thuế suất</th><th>Tổng</th></tr></thead><tbody>${row.lines.map(l=>`<tr><td>${e(l.name)}<small class="cell-sub">${l.from?date(l.from)+' – '+date(l.to):''} ${l.days?l.days+' ngày':''}</small></td><td>${money(l.net)}</td><td>${l.taxRate}%</td><td>${money(l.total)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-total">Tổng: <strong>${money(row.total)}</strong> · Đã thu: ${money(row.paid)} · Còn lại: ${money(row.total-row.paid)}</div>`;
 if(row.lines&&S.page==='journalEntries')content+=`<h3>Bút toán cân Nợ / Có</h3><table><thead><tr><th>Tài khoản</th><th>Nợ</th><th>Có</th></tr></thead><tbody>${row.lines.map(l=>`<tr><td>${e(l.account)} · ${e((S.cache.accounts||[]).find(a=>a.accountNumber===l.account)?.name||'')}</td><td>${money(l.debit)}</td><td>${money(l.credit)}</td></tr>`).join('')}</tbody></table>`;
 if(row.lines&&S.page==='invoices'){const payments=(S.cache.payments||[]).filter(p=>p.invoiceId===row.id);content+=`<h3>Lịch sử thu tiền</h3>${payments.map(p=>`<p class="history-line">${date(p.date)} · ${e(p.method)} · <strong>${money(p.amount)}</strong></p>`).join('')||'<p class="muted">Chưa có khoản thu.</p>'}`;}
 if(S.page==='projectFlows')content+=`<h3>Tiến độ vòng đời</h3><ol class="flow-steps">${row.steps.map((step,index)=>`<li><strong>${e(step.name)}</strong><span>${e(step.department)} · ${index<row.currentStep||row.status==='Đã hoàn thành'?'Đã bàn giao':index===row.currentStep?'Đang thực hiện':'Chưa đến bước'}</span><small>${e(step.document)}</small></li>`).join('')}</ol><h3>Lịch sử bàn giao</h3>${row.history.map(h=>`<p class="history-line">${e(h.name)} · ${e(h.confirmedAt)} · <a href="${e(h.documentUrl)}" target="_blank" rel="noopener noreferrer">${e(h.document)}</a></p>`).join('')||'<p class="muted">Chưa chuyển bước.</p>'}`;
 if(S.page==='qualityChecks'&&row.photo)content+=`<h3>Ảnh hiện trường</h3><img class="quality-photo" src="${e(row.photo)}" alt="Ảnh minh chứng đánh giá chất lượng">`;
 openModal(row.name||row.code,content,null);}
function generateInvoice(){const fields=[{key:'contractId',label:'Hợp đồng',type:'select',ref:'contracts',required:true},{key:'period',label:'Kỳ hóa đơn',type:'month',required:true}];openModal('Lập hóa đơn theo kỳ','<p class="modal-note">Tự tính giá hiệu lực, miễn phí thuê, tỷ giá và thuế từng dòng. Chỉ số công tơ phải nhập trước khi lập hóa đơn.</p><div class="form-grid">'+fields.map(f=>fieldHTML(f)).join('')+'</div>','Lập hóa đơn',async form=>{await api('/invoices/generate',Object.fromEntries(form));toast('Đã lập hóa đơn và lưu số liệu tại thời điểm phát hành.');});}
function workflow(id,action){const row=S.items.find(r=>r.id===id);const collection=S.page;const labels={advance:'Xác nhận chuyển bước dự án',receiveDeposit:'Ghi nhận nhận tiền cọc',reverse:'Lập bút toán đảo',receive:collection==='inventoryItems'?'Nhập vật tư':'Xác nhận nhận hàng',issue:'Xuất vật tư',pay:collection==='invoices'?'Ghi nhận thu tiền':'Thanh toán khoản chi',close:'Thanh lý hợp đồng',refundDeposit:'Hoàn trả tiền cọc',submit:'Gửi công việc để duyệt',approve:'Phê duyệt',reject:'Trả lại để làm lại',assign:'Phân công xử lý',resolve:'Hoàn tất xử lý',accept:'Nghiệm thu yêu cầu'};let fields=[],note='';
 if(action==='advance'){fields=[{key:'documentUrl',label:row.steps[row.currentStep].document+' (liên kết)',type:'url',required:true}];if(row.currentStep+1<row.steps.length)fields.push({key:'nextOwnerId',label:'Người bước kế tiếp ('+row.steps[row.currentStep+1].department+')',type:'select',ref:'employees',required:true},{key:'nextDueDate',label:'Hạn hoàn thành bước kế tiếp',type:'date',required:true});note='Chỉ chuyển sau khi công việc hiện tại đã được duyệt. Hệ thống sinh công việc và bàn giao cho người phụ trách bước kế tiếp.';}
 if(action==='receiveDeposit'){fields=[{key:'amount',label:'Số cọc nhận (VNĐ)',type:'number',min:1,max:row.deposit-Number(row.depositReceived||0),required:true},{key:'date',label:'Ngày nhận',type:'date',required:true},{key:'method',label:'Hình thức',type:'select',options:['Chuyển khoản','Tiền mặt'],required:true}];note='Cọc là khoản giữ hộ, không ghi nhận doanh thu. Còn phải nhận: '+money(row.deposit-Number(row.depositReceived||0))+'.';}
 if(action==='reverse'){fields=[{key:'date',label:'Ngày hạch toán điều chỉnh',type:'date',required:true},{key:'reason',label:'Lý do đảo bút toán',type:'textarea',required:true}];note='Tạo bút toán Nợ/Có đảo trong kỳ chưa khóa, giữ nguyên bản gốc. Không tự thay công nợ hoặc giao dịch nghiệp vụ; cần đối soát các sổ liên quan.';}
 if(collection==='inventoryItems'&&['receive','issue'].includes(action)){fields=[{key:'quantity',label:'Số lượng',type:'number',min:0.01,required:true},{key:'date',label:'Ngày nhập xuất',type:'date',required:true},{key:'notes',label:'Lý do / chứng từ',type:'textarea',required:true}];note='Tồn kho hiện tại: '+num(row.quantity)+' '+row.unit+'. Ghi nhận vật tư thực tế, không tự hạch toán giá trị kho.';}
 if(action==='pay'&&collection==='invoices'){fields=[{key:'amount',label:'Số tiền thu (VNĐ)',type:'number',min:1,max:row.total-row.paid,required:true},{key:'date',label:'Ngày thu',type:'date',required:true},{key:'method',label:'Hình thức',type:'select',options:['Chuyển khoản','Tiền mặt','Cấn trừ cọc'],required:true},{key:'reference',label:'Mã giao dịch / ghi chú',type:'text'}];note='Dư nợ hiện tại: '+money(row.total-row.paid);}
 if(action==='pay'&&collection==='expenses')fields=[{key:'date',label:'Ngày thanh toán',type:'date',required:true}];
 if(action==='close'){fields=[{key:'date',label:'Ngày đóng hợp đồng',type:'date',required:true},{key:'noticeMonths',label:'Số tháng đã báo trước',type:'number',min:0,required:true},{key:'reason',label:'Lý do thanh lý',type:'textarea',required:true}];note='Dừng trước hạn: đủ báo trước mặc định bồi thường 2 tháng; không đủ là 4 tháng. Mặt bằng sẽ được giải phóng, kỳ tương lai chưa thu sẽ hủy. Cọc chưa tự hoàn.';}
 if(action==='refundDeposit')note='Số cọc còn giữ: '+money(row.depositBalance)+'. Thao tác này ghi nhận hoàn cọc thủ công; hãy xác nhận nghĩa vụ bồi thường và công nợ đã được xử lý.';
 if(action==='reject')fields=[{key:'reason',label:'Lý do yêu cầu làm lại',type:'textarea',required:true}];
 if(action==='assign')fields=[{key:'assignee',label:'Người xử lý',type:'text',required:true}];
 if(action==='submit')note='Công việc cần có ngày hoàn thành không nằm trong tương lai. Nếu bị trả lại, hãy cập nhật công việc rồi gửi duyệt lại.';
 openModal(labels[action],`<p class="modal-note">${e(note||'Xác nhận thao tác cho '+(row.name||row.code)+'.')}</p><div class="form-grid">${fields.map(f=>fieldHTML(f,action==='pay'?{amount:row.total-row.paid}:{})).join('')}</div>${action==='refundDeposit'?'<label class="checkbox-field"><input name="confirmCompensation" type="checkbox" required> Tôi đã xử lý nghĩa vụ bồi thường theo biên bản thanh lý.</label>':''}`,'Xác nhận',async form=>{const data=Object.fromEntries(form);if(data.amount)data.amount=Number(data.amount);if(action==='refundDeposit')data.confirmCompensation=true;await api(`/records/${collection}/${id}/actions`,{...data,action});toast('Đã cập nhật nghiệp vụ và ghi nhật ký.');});}
function printInvoice(row){const win=window.open('','_blank');if(!win){toast('Cho phép cửa sổ in để lưu PDF.',true);return;}const doc=row.snapshot;win.document.write(`<!doctype html><html lang="vi"><head><meta charset="UTF-8"><title>${e(row.code)}</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:45px auto;color:#24352f}h1{color:#0c594f}table{width:100%;border-collapse:collapse;margin:25px 0}td,th{border-bottom:1px solid #ddd;padding:14px;text-align:left}.note{font-size:12px;color:#777}.total{text-align:right;font-size:20px}@media print{button{display:none}body{margin:0}}</style></head><body><h2>${e(doc.entity.name)}</h2><p>${e(doc.entity.address||'')}</p><h1>THÔNG BÁO THANH TOÁN</h1><p>Mã: ${e(row.code)} · Kỳ: ${e(row.period)}</p><p>Khách thuê: <strong>${e(doc.tenant.name)}</strong></p><p>Mặt bằng: ${e(doc.unit.name)} · Hợp đồng: ${e(doc.contract.code)}</p><table><thead><tr><th>Nội dung</th><th>Trước thuế</th><th>Thuế suất</th><th>Thuế</th><th>Tổng</th></tr></thead><tbody>${row.lines.map(l=>`<tr><td>${e(l.name)}</td><td>${money(l.net)}</td><td>${l.taxRate}%</td><td>${money(l.tax)}</td><td>${money(l.total)}</td></tr>`).join('')}</tbody></table><p class="total">Tổng phải thu: <strong>${money(row.total)}</strong></p><p class="total">Còn lại: <strong>${money(row.total-row.paid)}</strong></p><p>Hạn thanh toán: ${date(row.dueDate)}</p><p class="note">Chứng từ nội bộ. Không thay thế hóa đơn điện tử hợp pháp. Chọn In → Lưu thành PDF trong trình duyệt.</p><button id="print-invoice-button">In / Lưu PDF</button></body></html>`);win.document.close();win.document.querySelector('#print-invoice-button').addEventListener('click',()=>win.print());}
function cashflow(){const r=S.report;shell(`<div class="stat-grid">${stat('wallet','Thực thu',compact(r.cashIn),'Không gồm cấn trừ cọc')}${stat('credit','Thực chi',compact(r.cashOut),'Khoản chi đã thanh toán','amber')}${stat('chart','Dòng tiền thuần',compact(r.cashIn-r.cashOut),'Dòng tiền trong kỳ','blue')}${stat('building','Giá trị mặt bằng trống',compact(r.vacantValue),'Giá chào thuê × m² trống','purple')}</div><section class="card full-chart"><div class="card-heading"><h2>Dòng tiền thực tế & dự báo</h2><div class="chart-legend"><span><i class="legend-in"></i>Thu</span><span><i class="legend-out"></i>Chi</span></div></div>${chart(r.months)}<p class="chart-note">${e(r.forecastNote)}</p></section><div class="two-columns"><section class="card"><div class="card-heading"><h2>Tuổi nợ phải thu</h2></div><div class="aging-list">${r.aging.map(a=>`<div><span>${e(a.name)}</span><div class="progress-track"><i style="width:${r.debt?a.total/r.debt*100:0}%"></i></div><strong>${money(a.total)}</strong></div>`).join('')}</div></section><section class="card"><div class="card-heading"><h2>Thuế GTGT theo pháp nhân</h2></div><div class="table-scroll"><table><thead><tr><th>Pháp nhân</th><th>Đầu ra</th><th>Đầu vào</th><th>Chênh lệch</th></tr></thead><tbody>${r.taxes.map(t=>`<tr><td>${e(t.name)}</td><td>${compact(t.output)}</td><td>${compact(t.input)}</td><td>${compact(t.output-t.input)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-cell">Chưa có dữ liệu thuế trong kỳ.</td></tr>'}</tbody></table></div><p class="chart-note">Tổng hợp phục vụ đối soát nội bộ; chưa lập hoặc nộp tờ khai thuế.</p></section></div><section class="card"><div class="card-heading"><h2>Hiệu quả dự án</h2></div><div class="table-scroll"><table><thead><tr><th>Dự án</th><th>Doanh thu trước thuế</th><th>Chi phí ghi nhận</th><th>Lãi / lỗ</th><th>Biên lợi nhuận</th></tr></thead><tbody>${r.project.map(p=>`<tr><td><strong>${e(p.name)}</strong></td><td>${money(p.revenue)}</td><td>${money(p.cost)}</td><td class="${p.profit<0?'text-red':'text-teal'}">${money(p.profit)}</td><td>${num(p.margin)}%</td></tr>`).join('')}</tbody></table></div></section>`);}

async function ledger(){const result=await api('/ledger?period='+S.period+(S.entity?'&legalEntityId='+S.entity:''));shell(`<div class="info-banner">${icon('shield',17)}<span>Hạch toán kép tự động: hóa đơn → phải thu/doanh thu/thuế; khoản thu → tiền/phải thu; duyệt chi → chi phí/thuế đầu vào/phải trả; trả tiền → phải trả/tiền. Đây là sổ nội bộ, chưa thay thế phần mềm kế toán hoặc báo cáo tài chính pháp định.</span></div><div class="stat-grid">${stat('receipt','Phát sinh Nợ',compact(result.totalDebit),'Tổng Nợ trong kỳ')}${stat('receipt','Phát sinh Có',compact(result.totalCredit),'Tổng Có trong kỳ','blue')}${stat('check','Chênh lệch',compact(result.totalDebit-result.totalCredit),'Bút toán bắt buộc cân Nợ/Có','amber')}${stat('list','Tài khoản',result.accounts.length,'Danh mục kế toán','purple')}</div><section class="card"><div class="card-heading"><h2>Bảng cân đối tài khoản</h2><span class="tag">${e(S.period)}</span></div><div class="table-scroll"><table><thead><tr><th>Tài khoản</th><th>Tên</th><th>Phát sinh Nợ</th><th>Phát sinh Có</th><th>Dư Nợ lũy kế</th><th>Dư Có lũy kế</th></tr></thead><tbody>${result.accounts.map(a=>`<tr><td class="code-cell">${e(a.accountNumber)}</td><td>${e(a.name)}</td><td>${money(a.debit)}</td><td>${money(a.credit)}</td><td>${money(a.debitBalance)}</td><td>${money(a.creditBalance)}</td></tr>`).join('')}</tbody></table></div></section>`);}

async function payroll(){const result=await api('/payroll?period='+S.period);shell(`<div class="info-banner amber-banner">${icon('shield',18)}<span>${e(result.notice)} Bản MVP dùng thưởng tuyến tính theo điểm KPI, chưa áp dụng ngạch/bậc hoặc thuế TNCN.</span></div><section class="card records-card"><div class="card-heading"><h2>Đối chiếu lương cũ / lương đề xuất</h2><span class="tag">${e(S.period)}</span></div><div class="table-scroll"><table><thead><tr><th>Nhân sự</th><th>Phòng ban</th><th>Điểm KPI</th><th>Lương cơ bản</th><th>Thưởng thử</th><th>Lương đề xuất</th><th>Khung KPI</th><th>Chi tiết</th></tr></thead><tbody>${result.items.map((p,i)=>`<tr><td><strong>${e(p.employee.name)}</strong><small class="cell-sub">${e(p.employee.position)}</small></td><td>${e(p.employee.department)}</td><td>${num(p.score)}%</td><td>${money(p.oldSalary)}</td><td>${money(p.bonus)}</td><td class="text-teal">${money(p.proposedSalary)}</td><td>${badge(p.weight===100?'Đủ trọng số':'Chưa đủ',p.weight===100?'green':'amber')}</td><td><button class="row-button" data-payroll="${i}">Cách tính</button></td></tr>`).join('')}</tbody></table></div></section>`);document.querySelectorAll('[data-payroll]').forEach(button=>button.onclick=()=>{const p=result.items[Number(button.dataset.payroll)];openModal('Cách tính: '+p.employee.name,`<p class="modal-note">Thưởng thử = thưởng tối đa × tổng (% hoàn thành × trọng số). Mức hoàn thành mỗi chỉ tiêu giới hạn 120%; chỉ tính thưởng khi tổng trọng số = 100%.</p><table><thead><tr><th>Chỉ tiêu</th><th>Thực hiện / Mục tiêu</th><th>Trọng số</th><th>Hoàn thành</th></tr></thead><tbody>${p.details.map(k=>`<tr><td>${e(k.name)}</td><td>${num(k.actual)} / ${num(k.target)}</td><td>${k.weight}%</td><td>${num(k.achievement)}%</td></tr>`).join('')}</tbody></table><p>Thưởng tối đa: ${money(p.employee.bonusCap)}</p><strong>Thưởng chạy thử: ${money(p.bonus)}</strong>`,null);});}
async function showModel(id){try{const {scenarios}=await api('/appraisals/'+id+'/calculate');const row=lookup('appraisals',id)||S.items.find(r=>r.id===id);openModal('Thẩm định: '+row.name,`<p class="modal-note">${scenarios[0].months} tháng. Kịch bản thay đổi lấp đầy và chi phí; giả định tiền cọc thu hồi cuối vòng đời. IRR là giá trị gần đúng khi có nghiệm trong miền tìm kiếm.</p><div class="scenario-grid">${scenarios.map(s=>`<article class="scenario ${s.name==='Cơ sở'?'base':''}"><h3>${e(s.name)}</h3><dl><dt>NPV</dt><dd>${compact(s.npv)}</dd><dt>Lãi/lỗ dòng tiền vòng đời</dt><dd>${compact(s.profit)}</dd><dt>Hòa vốn</dt><dd>${s.breakeven?'Tháng '+s.breakeven:'Chưa hòa vốn'}</dd><dt>IRR năm</dt><dd>${s.irr===null?'Không có nghiệm':num(s.irr)+'%'}</dd><dt>Lấp đầy hòa vốn</dt><dd>${num(s.minimumOccupancy)}%</dd></dl></article>`).join('')}</div><h3>Dòng tiền kịch bản cơ sở</h3><div class="table-scroll model-timeline"><table><thead><tr><th>Tháng</th><th>Lấp đầy</th><th>Doanh thu</th><th>Chi phí</th><th>Dòng tiền</th><th>Lũy kế</th></tr></thead><tbody>${scenarios[1].timeline.map(t=>`<tr><td>${t.month}</td><td>${t.occupancy}%</td><td>${compact(t.revenue)}</td><td>${compact(t.cost)}</td><td>${compact(t.cash)}</td><td>${compact(t.cumulative)}</td></tr>`).join('')}</tbody></table></div>`,null);}catch(err){toast(err.message,true);}}
const moduleStatus={
 'NT-01':['Một phần','Danh mục và mã tự sinh, chống trùng; chưa gộp bản ghi và đổi mã hàng loạt.'], 'NT-02':['Một phần','Đăng nhập phiên, 6 vai trò, phạm vi pháp nhân/nhân sự/khách thuê; chưa Google SSO và quyền từng cột tùy biến.'], 'NT-03':['Một phần','REST API, phân trang, truy vết, cap_nhat_tu; chưa OAuth2/API key hoặc webhook ký và retry.'], 'NT-04':['Một phần','Audit before/after và khóa kỳ; chưa workflow bút toán điều chỉnh/khôi phục.'],
 'L1-01':['Một phần','Công việc theo phòng, nghĩa vụ/chức danh, 4 trạng thái và hàng đợi duyệt.'], 'L1-02':['Một phần','Công việc PKD; chưa toàn bộ chỉ số bán hàng tự động.'], 'L1-03':['Một phần','Công việc BQL, sự cố, bảo trì và giao diện điện thoại.'], 'L1-04':['Một phần','Công việc MKT; chưa đối soát attribution khách hàng.'], 'L1-05':['Một phần','Công việc HCNS; chưa tuyển dụng/mua sắm đầy đủ.'], 'L1-06':['Một phần','Báo cáo gộp 5 phòng tự động theo kỳ, trạng thái và người.'], 'L1-07':['Một phần','Lương cơ bản và mức thưởng; chưa thang/ngạch/bậc hiệu lực theo ngày.'], 'L1-08':['Một phần','KPI theo chức danh, trọng số, nguồn số, chốt kỳ; chưa khung thưởng nhiều ngưỡng.'], 'L1-09':['Một phần','Chạy thử lương cũ/mới, hiển thị cách tính; chưa biên bản hiệu chỉnh.'], 'L1-10':['Chưa triển khai','Chưa trả lương chính thức hoặc xử lý khiếu nại.'], 'L1-11':['Một phần','Thuế từng dòng và tổng hợp đa pháp nhân; chưa tờ khai thuế.'],
 'L2-01':['Một phần','Hợp đồng, giá/tỷ giá theo ngày, công tơ, VAT, hóa đơn nội bộ, thu nhiều lần, cọc, thanh lý, tuổi nợ. Chưa e-invoice/email và tách gộp mặt bằng.'], 'L2-02':['Một phần','Đề nghị chi → duyệt → thanh toán, chi phí bảo trì; chưa tự sinh chi định kỳ.'], 'L2-03':['Một phần','Thu chi thực tế và dự báo tối thiểu 3 tháng; chưa số dư ngân hàng/ngưỡng cảnh báo.'], 'L2-04':['Một phần','Lãi lỗ từng dự án theo kỳ; chưa đối chiếu tự động giả định thẩm định.'], 'L2-05':['Một phần','Biên lợi nhuận dự án đang vận hành theo tháng.'], 'L2-06':['Một phần','Mô hình 120 tháng, 3 kịch bản, NPV/IRR/hòa vốn; chưa so sánh nhiều tòa và mô hình thuê chủ nhà nhiều giai đoạn.'], 'L2-07':['Một phần','Mô hình 60 tháng dùng khung thẩm định; chưa giá bán theo thỏa thuận hợp tác.'], 'L2-08':['Một phần','Mô hình Setup 60 tháng, vốn đầu tư, giá bán và hoàn vốn.'],
 'L2-09':['Một phần','Khung 7 bước Master Lease 10 năm, giao người/đơn vị, tài liệu, công việc tự sinh, chặn chuyển khi chưa duyệt.'], 'L2-10':['Một phần','Khung Gems Office 5 năm dùng chung cơ chế bàn giao.'], 'L2-11':['Một phần','Khung Managed Office OUT, xác nhận từng bước và hồ sơ.'], 'L2-12':['Một phần','Khung Managed Office IN dùng chung workflow.'], 'L2-13':['Một phần','Khung Setup, bàn giao và theo dõi hoàn vốn.'], 'L2-14':['Một phần','Phiếu chất lượng theo người/tòa/vị trí, điểm, ảnh và GPS nhập tay; điểm đưa vào KPI. Chưa bộ tiêu chuẩn cấu hình/tần suất tự sinh.'], 'L2-15':['Một phần','Dashboard tổng hợp tài chính, lấp đầy, hiệu quả, phòng ban và cảnh báo, lọc pháp nhân/tòa.'], 'L2-16':['Một phần','Công việc vòng đời có bàn giao giữa PKD/TCKT/BQL và lưu thời điểm; chưa cấu hình workflow liên phòng tùy ý.'],
 'VH-01':['Một phần','Thiết bị, lịch/chu kỳ và nhật ký bảo trì sinh đề nghị chi; chưa ảnh và thông báo đẩy.'], 'VH-02':['Một phần','Tiếp nhận, SLA, phân công, xử lý, khách nghiệm thu, chuyển phí qua hóa đơn; chưa ảnh/biên bản.'], 'CS-01':['Một phần','CRM liên hệ và lịch sử hợp đồng, cảnh báo tái ký trong 90 ngày; chưa khảo sát.'], 'CS-02':['Một phần','Thông báo đọc trên portal; chưa gửi email/SMS/Zalo hoặc nhắc nợ đa cấp.'], 'PT-01':['Một phần','Tài khoản khách thuê riêng, hợp đồng/hóa đơn/thanh toán/công tơ/yêu cầu/thông báo trong phạm vi khách.'], 'PT-02':['Chưa triển khai','Web responsive; chưa ứng dụng native, push hoặc xuất bản lên kho ứng dụng.'], 'PT-03':['Chưa triển khai','Thu thủ công, chưa QR theo hóa đơn hoặc kết nối ngân hàng/đối soát tự động.']};
function modules(){const spec=S.meta.spec;const partial=Object.values(moduleStatus).filter(([s])=>s==='Một phần').length;shell(`<div class="stat-grid">${stat('grid','Module yêu cầu',38,'Trích nguyên từ BaoGia_Module')}${stat('list','Yêu cầu nghiệp vụ',41,'Phụ lục A, B, C, D','blue')}${stat('check','Có chức năng nền',partial,'Trạng thái: triển khai một phần','teal')}${stat('clock','Chưa triển khai',38-partial,'Hiển thị rõ, không giả lập tích hợp','amber')}</div><div class="info-banner">${icon('file',17)}<span>Nguồn: ${e(spec.source)}. Nội dung file là yêu cầu nghiệp vụ để đối chiếu, không phải dữ liệu giao dịch hoặc lệnh thực thi.</span></div><section class="card"><div class="card-heading"><h2>Phạm vi triển khai theo 38 module</h2></div><div class="table-scroll"><table class="module-table"><thead><tr><th>Mã</th><th>Module</th><th>Trạng thái</th><th>Đã có / còn thiếu</th></tr></thead><tbody>${spec.modules.map(m=>`<tr><td class="code-cell">${e(m.code)}</td><td><strong>${e(m.name)}</strong><small class="cell-sub">${e(m.group)}</small></td><td>${badge(moduleStatus[m.code]?.[0]||'Chưa triển khai',moduleStatus[m.code]?.[0]==='Một phần'?'blue':'gray')}</td><td>${e(moduleStatus[m.code]?.[1]||'')}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-heading"><h2>41 yêu cầu nghiệp vụ từ Excel</h2></div><div class="requirements-list">${spec.requirements.map(r=>`<details><summary><span class="tag">${e(r.id)}</span>${e(r.modules)}</summary><p>${e(r.description)}</p></details>`).join('')}</div></section>`);}
async function audit(){const result=await api('/audit');shell(`<section class="card"><div class="card-heading"><h2>100 thay đổi gần nhất</h2><span class="tag">Chỉ quản trị viên</span></div><div class="table-scroll"><table><thead><tr><th>Thời gian</th><th>Người thực hiện</th><th>Thao tác</th><th>Phân hệ</th><th>Chi tiết</th></tr></thead><tbody>${result.items.map((r,i)=>`<tr><td>${e(new Date(r.date).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'}))}</td><td>${e(r.actor)}</td><td>${badge(r.action,'blue')}</td><td>${e(S.meta.schemas[r.collection]?.label||r.collection)}</td><td><button class="row-button" data-log="${i}">Trước / sau</button></td></tr>`).join('')}</tbody></table></div></section>`);document.querySelectorAll('[data-log]').forEach(button=>button.onclick=()=>{const row=result.items[Number(button.dataset.log)];openModal('Chi tiết thay đổi','<div class="two-columns"><section><h3>Trước</h3><pre>'+e(row.before?JSON.stringify(JSON.parse(row.before),null,2):'Không có')+'</pre></section><section><h3>Sau</h3><pre>'+e(row.after?JSON.stringify(JSON.parse(row.after),null,2):'Không có')+'</pre></section></div>',null);});}
async function users(){const result=await api('/users');shell(`<div class="info-banner">${icon('shield',17)}<span>Quyền được kiểm tra trên API. Nhân viên gắn hồ sơ nhân sự; khách thuê chỉ xem dữ liệu của khách được gán.</span></div><section class="card"><div class="card-heading"><h2>Tài khoản nội bộ & khách thuê</h2><button class="button primary small-button" id="add-user">${icon('plus',16)} Tạo tài khoản</button></div><div class="table-scroll"><table><thead><tr><th>Tên</th><th>Tài khoản</th><th>Vai trò</th><th>Phạm vi</th></tr></thead><tbody>${result.items.map(u=>`<tr><td><strong>${e(u.name)}</strong></td><td>${e(u.username)}</td><td>${badge(roles[u.role],'blue')}</td><td>${e(u.scope.tenantId?label('tenants',u.scope.tenantId):u.scope.employeeId?label('employees',u.scope.employeeId):u.scope.legalEntityId?label('legalEntities',u.scope.legalEntityId):'Theo quyền vai trò, toàn doanh nghiệp')}</td></tr>`).join('')}</tbody></table></div></section>`);document.querySelector('#add-user').onclick=()=>{const fields=[{key:'name',label:'Tên hiển thị',type:'text',required:true},{key:'username',label:'Tên đăng nhập',type:'text',required:true},{key:'password',label:'Mật khẩu (ít nhất 12 ký tự)',type:'password',required:true},{key:'role',label:'Vai trò',type:'select',options:Object.keys(roles),required:true},{key:'legalEntityId',label:'Giới hạn pháp nhân (tùy chọn)','type':'select',ref:'legalEntities'},{key:'employeeId',label:'Hồ sơ nhân sự (nhân viên/kỹ thuật)',type:'select',ref:'employees'},{key:'tenantId',label:'Khách thuê (tài khoản portal)',type:'select',ref:'tenants'}];openModal('Tạo tài khoản','<div class="form-grid">'+fields.map(f=>fieldHTML(f)).join('')+'</div>','Tạo tài khoản',async form=>{const data=Object.fromEntries(form);await api('/users',{name:data.name,username:data.username,password:data.password,role:data.role,scope:Object.fromEntries(['legalEntityId','employeeId','tenantId'].filter(k=>data[k]).map(k=>[k,data[k]]))});toast('Đã tạo tài khoản.');});};}
async function periods(){const result=await api('/periods');shell(`<div class="info-banner amber-banner">${icon('shield',18)}<span>Sau khi chốt, hóa đơn, thu chi, công việc và KPI của kỳ chỉ đọc. Bản MVP chưa có bút toán điều chỉnh hoặc mở lại kỳ.</span></div><section class="card"><div class="card-heading"><h2>Kỳ đã chốt</h2><button class="button primary small-button" id="lock-period">${icon('shield',16)} Chốt kỳ ${e(S.period)}</button></div><div class="table-scroll"><table><thead><tr><th>Kỳ</th><th>Trạng thái</th><th>Thời điểm chốt</th><th>Doanh thu chụp tại thời điểm chốt</th></tr></thead><tbody>${result.items.map(p=>`<tr><td>${e(p.period)}</td><td>${badge(p.status,'green')}</td><td>${e(new Date(p.createdAt).toLocaleString('vi-VN',{timeZone:'Asia/Bangkok'}))}</td><td>${money(p.snapshot.revenue)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-cell">Chưa có kỳ đã chốt.</td></tr>'}</tbody></table></div></section>`);document.querySelector('#lock-period').onclick=()=>openModal('Chốt kỳ '+S.period,'<p class="modal-note">Thao tác khóa số liệu của kỳ, không thể mở lại trên giao diện hiện tại. Hãy đối soát hóa đơn, thu chi và giải quyết hàng đợi duyệt trước khi xác nhận.</p>','Xác nhận chốt kỳ',async()=>{await api('/periods',{period:S.period});toast('Đã đóng băng kỳ và lưu báo cáo đối soát.');});}
function portal(){const invoices=S.cache.invoices||[],contracts=S.cache.contracts||[],announcements=S.cache.announcements||[];shell(`<div class="stat-grid">${stat('file','Hợp đồng của bạn',contracts.filter(c=>c.status==='Hiệu lực').length,'Chỉ dữ liệu khách thuê được cấp')}${stat('receipt','Hóa đơn chưa thanh toán',S.report.debtInvoices,'Xem chi tiết tại phân hệ hóa đơn','blue')}${stat('wallet','Dư nợ hiện tại',compact(S.report.debt),'Đã trừ các lần thanh toán','amber')}${stat('life','Yêu cầu đang xử lý',S.report.tickets.length,'Gửi yêu cầu đến ban quản lý','purple')}</div><div class="portal-links">${[['contracts','Hợp đồng & mặt bằng','file'],['invoices','Hóa đơn & thanh toán','receipt'],['meters','Chỉ số điện nước','gauge'],['tickets','Yêu cầu dịch vụ','life']].map(([key,text,ico])=>`<button class="card portal-link" data-page="${key}">${icon(ico,26)}<strong>${text}</strong>${icon('arrow',17)}</button>`).join('')}</div><section class="card"><div class="card-heading"><h2>Thông báo tòa nhà</h2></div><div class="announcement-list">${announcements.map(a=>`<article><span class="eyebrow">${date(a.publishDate)} · ${e(label('buildings',a.buildingId))}</span><h3>${e(a.name)}</h3><p>${e(a.content)}</p></article>`).join('')||'<p class="empty-cell">Chưa có thông báo.</p>'}</div></section>`);bindNav();}
function download(value,name,type){const url=URL.createObjectURL(new Blob([value],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function downloadJSON(){try{const result=await api('/export');download(JSON.stringify(result,null,2),'gems-erp-'+dateToday()+'.json','application/json');toast('Đã xuất toàn bộ dữ liệu nghiệp vụ, không kèm thông tin xác thực.');}catch(err){toast(err.message,true);}}
function exportCSV(){const schema=S.meta.schemas[S.page];const keys=['code',...schema.columns.filter(k=>k!=='code')];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const data=[keys,...S.items.map(row=>keys.map(key=>{const field=schema.fields.find(f=>f.key===key);return field?.ref?label(field.ref,row[key]):row[key];}))];download('\ufeff'+data.map(row=>row.map(cell).join(',')).join('\r\n'),S.page+'-'+dateToday()+'.csv','text/csv;charset=utf-8');toast('Đã xuất các bản ghi đang hiển thị.');}
function importRecords(){openModal('Nhập JSON: '+title(),`<p class="modal-note">Chọn file JSON chứa mảng bản ghi hoặc {"items":[…]}, tối đa 100 bản ghi/lần. Các khóa liên kết phải dùng ID có trong hệ thống. Toàn bộ đợt nhập sẽ hủy nếu một dòng không hợp lệ.</p><label class="form-field">File dữ liệu JSON<input id="import-file" type="file" accept="application/json,.json" required></label><p class="modal-note">Trường dữ liệu: ${e(S.meta.schemas[S.page].fields.map(f=>f.key).join(', '))}</p>`,'Kiểm tra & nhập',async()=>{const file=document.querySelector('#import-file').files[0];if(file.size>1024*1024)throw new Error('File vượt quá 1 MB.');const parsed=JSON.parse(await file.text());const result=await api('/import/'+S.page,{items:Array.isArray(parsed)?parsed:parsed.items});toast('Đã nhập '+result.count+' bản ghi.');});}
async function loadCache(){const pairs=await Promise.all(Object.keys(S.meta.schemas).map(async name=>{const result=await api('/records/'+name+'?limit=500');return [name,result.items];}));S.cache=Object.fromEntries(pairs);}
let refreshId=0;
async function refresh(){const requestId=++refreshId;if(!S.meta.schemas[S.page]&&!pageLabels[S.page])S.page='dashboard';if(S.user.role==='tenant'&&S.page==='dashboard')S.page='portal';const filters=new URLSearchParams({period:S.period,...(S.entity?{legalEntityId:S.entity}:{}),...(S.building?{buildingId:S.building}:{})});S.report=await api('/reports?'+filters);if(requestId!==refreshId)return;
 if(S.meta.schemas[S.page]){const q=new URLSearchParams({limit:25,page:S.pageNum,...(S.search?{q:S.search}:{}),...(S.entity?{legalEntityId:S.entity}:{}),...(S.building?{buildingId:S.building}:{})});const result=await api('/records/'+S.page+'?'+q);if(requestId!==refreshId)return;S.items=result.items;S.total=result.total;records();}
 else if(S.page==='ledger')await ledger();else if(S.page==='cashflow')cashflow();else if(S.page==='payroll')await payroll();else if(S.page==='modules')modules();else if(S.page==='audit')await audit();else if(S.page==='users')await users();else if(S.page==='periods')await periods();else if(S.page==='portal')portal();else dashboard();}
async function go(page){if(!S.meta.schemas[page]&&!pageLabels[page])return;S.page=page;S.search='';S.pageNum=1;location.hash=page;try{await refresh();window.scrollTo(0,0);}catch(err){toast(err.message,true);}}
function auth(initialized){app.innerHTML=`<div class="auth-layout"><section class="auth-branding"><a class="brand" href="#"><span class="brand-icon">${icon('gem',30)}</span><span>GEMS OFFICE<small>BUILDING ERP</small></span></a><div><p class="eyebrow">MỘT HỆ THỐNG. HAI LUỒNG LIÊN THÔNG.</p><h1>Quản lý tòa nhà.<br>Vận hành có<br><span>cơ sở.</span></h1><p>Kết nối tài sản, khách thuê, tài chính và hiệu suất nhân sự trong một không gian làm việc.</p><div class="auth-features"><span>${icon('building')} Danh mục đa tòa nhà</span><span>${icon('receipt')} Hợp đồng & tài chính</span><span>${icon('check')} Hiệu suất & phê duyệt</span></div></div><small>Thiết kế theo yêu cầu nghiệp vụ Gems Office.</small></section><section class="auth-form-wrap"><form id="auth-form" class="auth-form"><span class="auth-badge">${icon('shield',20)}</span><p class="eyebrow">${initialized?'CHÀO MỪNG TRỞ LẠI':'KHỞI TẠO KHÔNG GIAN LÀM VIỆC'}</p><h2>${initialized?'Đăng nhập hệ thống':'Bắt đầu với Gems ERP'}</h2><p>${initialized?'Sử dụng tài khoản được quản trị viên cấp.':'Tạo tài khoản quản trị đầu tiên. Bạn tự đặt mật khẩu; không có tài khoản mặc định.'}</p>${initialized?'':'<label class="form-field"><span>Họ tên quản trị viên</span><input name="name" required autocomplete="name" maxlength="100" placeholder="Họ và tên"></label>'}<label class="form-field"><span>Tên đăng nhập</span><input name="username" required minlength="3" maxlength="80" autocomplete="username" placeholder="admin hoặc email công ty"></label><label class="form-field"><span>Mật khẩu${initialized?'':' (ít nhất 12 ký tự)'}</span><input name="password" type="password" required ${initialized?'':'minlength="12"'} maxlength="128" autocomplete="${initialized?'current-password':'new-password'}" placeholder="Nhập mật khẩu"></label>${initialized?'':'<label class="checkbox-field"><input name="demo" type="checkbox" checked> Thêm dữ liệu minh họa để trải nghiệm ERP</label>'}<p class="form-error" id="auth-error" role="alert"></p><button class="button primary auth-submit" type="submit">${initialized?'Đăng nhập':'Tạo hệ thống ERP'} ${icon('arrow',17)}</button><p class="auth-footnote">${initialized?'Phiên đăng nhập hết hạn sau 8 giờ.':'Có thể bỏ chọn dữ liệu minh họa để bắt đầu với danh mục trống.'}</p></form></section></div>`;
 document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;const data=Object.fromEntries(new FormData(event.target));data.demo=data.demo==='on';try{await api(initialized?'/auth/login':'/auth/bootstrap',data);location.hash='dashboard';S.page='dashboard';await init();}catch(err){document.querySelector('#auth-error').textContent=err.message;}finally{button.disabled=false;}};}
async function init(){try{const status=await api('/auth/status');S.user=status.user;if(!S.user){auth(status.initialized);return;}S.meta=await api('/meta');await loadCache();await refresh();}catch(err){app.innerHTML=`<div class="connection-error">${icon('life',35)}<h1>Chưa kết nối được máy chủ ERP</h1><p>${e(err.message)}</p><p>Chạy ứng dụng bằng <code>npm run dev</code> để khởi động cả giao diện và API.</p><button class="button primary" id="retry-connection">Thử lại</button></div>`;document.querySelector('#retry-connection').onclick=init;}}
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1)||'dashboard';if(S.user&&page!==S.page)go(page);});
init();
